<!-- Static DOM retained for existing feature runtime. Keep IDs and classes stable. -->
<template>
<section v-pre id="questionnaireTemplateView" class="view">
          <div class="page-heading"><div><p class="eyebrow">TPRM SUBPAGE 03.5</p><h2>Questionnaire Templates</h2><p class="lede">Manage Due Diligence Questionnaire templates used for vendor assessments.</p></div><div class="csf-actions"><button class="button button-accent" id="templateNewButton" type="button">New template</button><span class="file-count" id="templateCount">0 templates</span></div></div>
          <div class="section-heading"><div><p class="eyebrow">TEMPLATE LIBRARY</p><h3>Available questionnaire templates</h3><p class="muted">Select which template to use when creating vendor assessments.</p></div></div><div class="excel-wrap"><table class="excel-table tprm-register-table"><thead><tr><th>Template Name</th><th>Description</th><th>Sections</th><th>Default</th><th>Actions</th></tr></thead><tbody id="templateBody"></tbody></table></div>
          <dialog id="templateModal" class="certification-modal"><form id="templateForm" class="risk-register-form"><input id="templateId" type="hidden"><div class="section-heading compact"><div><p class="eyebrow">QUESTIONNAIRE TEMPLATE</p><h3 id="templateFormTitle">New template</h3></div><span class="save-state" id="templateStatus">Ready</span></div><div class="risk-register-grid"><label>Template name<input id="templateName" required maxlength="200"></label><label>Description<textarea id="templateDescription" rows="3"></textarea></label><label>Set as default<input id="templateIsDefault" type="checkbox"></label></div><div class="section-heading compact"><div><p class="eyebrow">QUESTION SET</p><h3>Sections and questions</h3></div><button class="button button-quiet" id="templateAddSection" type="button">Add section</button></div><div id="templateSections" class="template-sections"></div><div class="csf-form-actions"><button class="button button-accent" type="submit">Save template</button><button class="button button-danger" id="templateDelete" type="button" hidden>Delete template</button><button class="button button-quiet" id="templateCancel" type="button">Close</button></div></form></dialog>
        </section>
</template>
